#include <iostream>

// GradeBook class definition
class GradeBook {
public:
    // const member function: guarantees it will not modify the calling object
    void displayMessage() const {
        std::cout << "Welcome to the Grade Book!" << std::endl;
    }
}; // Semicolon is mandatory

int main() {
    GradeBook myGradeBook;
    myGradeBook.displayMessage();
    return 0;
}

#include <iostream>

class BannerPrinter {
public:
    void printHeader() const {
        std::cout << "=== System Dashboard ===" << std::endl;
    }

    void printStatus() const {
        std::cout << "Status: Operational" << std::endl;
    }
};

int main() {
    // Instantiate an object of user-defined type BannerPrinter
    BannerPrinter printer;

    // Invoke member functions on the instance using the dot operator
    printer.printHeader();
    printer.printStatus();

    return 0;
}
